import{z as l,x as A,o as n,c as s,q as i,j as r,D as a,d as o,s as E,S as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Tokenizer：BPE / Unigram / Byte","description":"","frontmatter":{"title":"Tokenizer：BPE / Unigram / Byte","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tokenizer-design.md","filePath":"llm/tokenizer-design.md","lastUpdated":1791063341000}'),d={name:"llm/tokenizer-design.md"};function p(m,e,c,h,P,k){const t=A("Mermaid");return n(),s("div",null,[e[2]||(e[2]=i('<h1 id="tokenizer-bpe-unigram-byte" tabindex="-1">Tokenizer：BPE / Unigram / Byte <a class="header-anchor" href="#tokenizer-bpe-unigram-byte" aria-label="Permalink to &quot;Tokenizer：BPE / Unigram / Byte&quot;">​</a></h1><div class="epigraph"><p>把稀有词切成能在训练数据里反复见到的子词，翻译系统就不必为每个未见词准备一套开放词表。</p><footer>—— Sennrich, Haddow, Birch, Neural Machine Translation of Rare Words with Subword Units, ACL 2016</footer></div><p><a href="/llm/synthetic-pretrain">上一课</a>把合成数据写成预训练补丁：改写比凭空生成更可追溯，二者都要与真实文本按 token 下限混合，通顺度分类器会给完美语法的错误打高分。缺口是符号层。模型不直接吃 Unicode；切分算法决定哪些共现能被一个 token 看见，且与数据配比耦合——tokenizer 训练集的领域与语种，决定谁获得短符号。本课写 BPE、Unigram 与字节级三条承诺。不重讲合成崩塌。词表大小与压缩率下一课再定量；后课默认已经读完切分规则本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理想符号应在「压缩」与「可组合」之间：太小（字节）序列长、上下文窗口浪费；太大（整词）词表膨胀、长尾词永远学不够。子词是折中。还要处理噪声：网页拼写错误、混合脚本、HTML 残留。词表若在干净新闻上训练，到 C4 上会出现大量碎片与浪费。tokenizer 是数据管线的一部分，应在清洗去重之后的混合物上训练，并冻结后与模型版本绑定。</p><p><span class="marginnote">数字实例：同样是 &quot;tokenization&quot; 这个词——纯字节要 12 个 token，32K 词表的 BPE 大约切成 3-4 个，若整词收录只要 1 个。序列长度差三倍，同样的上下文窗口能装下的文本就差三倍，这就是「压缩」这一端实实在在的账。</span></p><p>未登录与分解稳定性也是问题。BPE 贪心切分对同一词在不同上下文中通常稳定；Unigram 采样切分故意不稳定以正则。训练用采样、推理用 Viterbi，是 Unigram 的常见搭配。ByT5 没有未登录，但「词」的概念完全交给注意力层，小模型可能学不齐。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>BPE（Sennrich 等人引入神经翻译）初始化词表为字符（或字节），统计相邻对频率，每次把当前最频繁的对合并成新符号，直到词表达到预定大小。切分时贪心：从左到右应用学到的合并。它不显式优化句子似然，优化的是「高频邻接被收成原子」。英语形态（<code>-ing</code>、<code>-ed</code>）会自然出现，因为它们频繁。</p><p><span class="marginnote">BPE 全名 Byte Pair Encoding，原本是 1950 年代的压缩算法：反复把文本中最常出现的相邻字节对换成一个新的符号。搬到 NLP 里，「最常出现的相邻对」约等于高频词根词缀——<code>un</code>、<code>ing</code>、<code>tion</code> 会被自然收成单 token，不是因为它有语言学含义，纯粹因为它出现得多。</span></p><p>Unigram（Kudo）假设句子由子词独立生成，用 EM 估计每个候选子词的概率，删掉对语料似然贡献小的符号，留下固定大小词表。切分可以取 Viterbi 最优，也可以按概率采样多条切分做正则。SentencePiece 把 Unigram 与 BPE 都做成不依赖预分词的实现，直接在原始文本上训练，对无空格语言关键。</p><p>字节级：ByT5 把输入当 UTF-8 字节，词表约 256 再加少量特殊符，没有子词合并。模型必须在深度里学习把字节组成词。代价是序列变长，注意力二次成本上升；收益是无未登录、对噪声与拼写更稳，且不需要一份与训练数据匹配的 tokenizer 快照。</p>',12)),(n(),r(B,null,{default:a(()=>[E(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%8E%9F%E5%A7%8B%E6%96%87%E6%9C%AC%22%5D%20--%3E%20BPE%5B%22BPE%EF%BC%9A%E9%A2%91%E6%AC%A1%E5%90%88%E5%B9%B6%22%5D%0A%20%20T%20--%3E%20UNI%5B%22Unigram%EF%BC%9A%E4%BC%BC%E7%84%B6%E5%88%A0%E8%AF%8D%22%5D%0A%20%20T%20--%3E%20BYT%5B%22Byte%EF%BC%9A%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%88%87%22%5D%0A%20%20BPE%20--%3E%20ID%5B%22%E6%95%B4%E6%95%B0%E5%BA%8F%E5%88%97%22%5D%0A%20%20UNI%20--%3E%20ID%0A%20%20BYT%20--%3E%20ID%0A%20%20ID%20--%3E%20LM%5B%22%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i('<h3 id="预分词与字节基" tabindex="-1">预分词与字节基 <a class="header-anchor" href="#预分词与字节基" aria-label="Permalink to &quot;预分词与字节基&quot;">​</a></h3><p>GPT-2 一类字节级 BPE 先把文本打成字节，再在字节上合并，避免 Unicode 字符表过大，也避免未见字符。传统 BPE 常先按空格分词再在词内合并，英语干净，中文、泰语、代码则依赖预分词是否合理。SentencePiece 的「把空格当成普通字符」让同一套算法跨语言。选择预分词，就是选择哪些边界永远不会被合并：空格预分词保证 token 不跨词；无预分词允许「词+后一词的首字母」这类合并，压缩率可能更高，语义边界更糊。</p><p><span class="marginnote">代码对预分词极敏感。按空格切会把缩进和运算符弄碎；按字节 BPE 可能把常用 API 收成单 token。tokenizer 必须在含代码的混合物上训练，否则 GitHub 文本会被切成过长序列，配比里写的代码 token 百分比并不等于代码「内容」百分比。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="合并与似然的差别" tabindex="-1">合并与似然的差别 <a class="header-anchor" href="#合并与似然的差别" aria-label="Permalink to &quot;合并与似然的差别&quot;">​</a></h3><p>BPE 的合并是确定性的频次贪心，可能留下对似然无用的符号，也可能把不该粘在一起的高频垃圾（网页模板片段）收成单 token——若在未去重的 Crawl 上训练 tokenizer，这一点很致命。Unigram 直接最大化语料的分词似然，删词有明确标准，但对候选初始集敏感：候选太穷，优化无从选择。实践中 Unigram 常从过完备的频率表或种子 BPE 出发。两者都不是形态学分析器；它们只是统计压缩器。Kudo 的子词正则利用 Unigram 的多切分，提高对拼写变体的稳健，这是 BPE 标准贪心切分没有的训练技巧。</p>',6)),(n(),r(B,null,{default:a(()=>[E(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%AF%8D%E8%A1%A8%E5%88%9D%E5%A7%8B%E5%8C%96%E4%B8%BA%E5%AD%97%E7%AC%A6%E6%88%96%E5%AD%97%E8%8A%82%22%5D%20--%3E%20S%5B%22%E7%BB%9F%E8%AE%A1%E8%AF%AD%E6%96%99%E4%B8%AD%E7%9B%B8%E9%82%BB%E5%AF%B9%E9%A2%91%E6%AC%A1%22%5D%0A%20%20S%20--%3E%20M%5B%22%E6%8A%8A%E6%9C%80%E9%AB%98%E9%A2%91%E5%AF%B9%E5%90%88%E5%B9%B6%E6%88%90%E6%96%B0%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20M%20--%3E%20V%7B%22%E8%AF%8D%E8%A1%A8%E8%BE%BE%E5%88%B0%E7%9B%AE%E6%A0%87%E5%A4%A7%E5%B0%8F%3F%22%7D%0A%20%20V%20--%3E%7C%22%E6%9C%AA%E5%88%B0%22%7C%20S%0A%20%20V%20--%3E%7C%22%E5%88%B0%22%7C%20F%5B%22%E5%86%BB%E7%BB%93%E8%AF%8D%E8%A1%A8%20%E6%8E%A8%E7%90%86%E6%97%B6%E8%B4%AA%E5%BF%83%E5%BA%94%E7%94%A8%E5%90%88%E5%B9%B6%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<p>字节模型把组合责任上移。ByT5 的实验表明，在足够深度与宽度下，字节级可以追上子词模型的许多任务，尤其在对噪声、罕见形态敏感的设定里；在计算匹配的条件下，更长的序列仍是税。解码器大模型后来仍普遍用字节级 BPE 而不是纯字节，是因为推理长度税比词表存储更贵。</p><p><span class="marginnote">特殊 token（BOS、EOS、PAD、掩码哨兵）必须进词表且永不拆。T5 的跨度哨兵是目标设计对 tokenizer 的侵入：噪声协议与词表一起版本化。换 UL2 或聊天模板而不换词表，要确认哨兵与保留字不冲突。</span></p><h3 id="与多语言、代码的耦合" tabindex="-1">与多语言、代码的耦合 <a class="header-anchor" href="#与多语言、代码的耦合" aria-label="Permalink to &quot;与多语言、代码的耦合&quot;">​</a></h3><p>同一套 32K 英语偏向 BPE，中文被切成单字或更碎，韩文、阿拉伯文同样吃亏。多语言要么放大词表，要么接受更长序列。Unigram 在多语言 SentencePiece 里常见，因为可以在联合语料上按似然分配词表名额——仍会偏向高资源，除非训练时对语言做平衡采样。这与领域配比是同一问题在符号层的投影：tokenizer 训练集的配比，决定谁拥有短 token。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>tokenizer 一旦冻结，改变词表等于改变嵌入矩阵，通常要重训或做复杂的嵌入初始化。不要在预训练中途「升级 tokenizer」。数据换代（新语言、新代码风格）只能忍受次优切分，或付出重训代价。因此第一刀应在目标混合物的样本上训练，而不是用一份英语维基词表撑过全部预训练。</p><p><span class="marginnote">初学者容易把 tokenizer 当成「把字变成数字」的无聊预处理，换一个无所谓。实际上换了词表，嵌入矩阵每一行的含义全变，等于逼模型换一门「外语」重学怎么读——这就是为什么词表冻结是硬约束，而不是工程偏好。</span></p><p>BPE 实现细节会造成不可复现：是否字节回退、如何处理 NFC/NFKC、是否把数字切成单数字。公开模型应发布 tokenizer 文件而不是只报词表大小。ByT5 的可复现性最好（几乎无词表），但与主流解码器工具链不兼容，KV 缓存与上下文长度都以更长序列计价。</p><p>不要把 tokenizer 当成与质量无关的预处理。它改变有效上下文、改变代码与多语言的真实份额、改变未登录行为。Gopher、Llama 报告的 token 数，都是某套切分下的计数；换 Unigram 或纯字节，同样字符的「训练预算」数字会变，缩放曲线不能跨词表直接比。</p><p><span class="marginnote">训练 tokenizer 的语料必须已经去重。否则高频转载段落会独占合并名额，词表里出现没有语言学意义的句子碎片。Lee 等人的去重不仅服务语言模型，也服务词表质量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BPE 按频次贪心合并；Unigram 按子词似然删词；ByT5 几乎在原始字节上建模。</li><li>预分词决定哪些边界不可跨；字节级 BPE 是大解码器里最常见的折中。</li><li>tokenizer 训练集的领域与语种配比，决定谁获得短符号，与数据配比耦合。</li><li>Unigram 可采样多切分做正则；BPE 默认切分更确定、更好部署。</li><li>纯字节无未登录、更抗噪声，但序列长度税高，大模型推理通常不选它当默认。</li><li>词表与特殊哨兵必须和训练目标、聊天模板一起版本化，中途更换代价接近重训。</li><li>出处：Sennrich et al.，BPE，ACL 2016；Kudo，Unigram / 子词正则，ACL 2018；Xue et al.，ByT5；数据侧对照 Raffel T5 与去重工作。</li></ul>',12))])}const _=l(d,[["render",p]]);export{u as __pageData,_ as default};
